"/* =====================================================================
   REAL-TIME INSPECTION REVIEW QUEUE - MODERN CLEAN LIGHT THEME
   Engineered for Industrial Quality Control & High-Visibility Monitoring
   ===================================================================== */

:root {
  /* Surfaces & Backgrounds */
  --bg-app: #f8fafc;
  --bg-card: #ffffff;
  --bg-card-sub: #f1f5f9;
  --bg-input: #ffffff;
  --border-color: #e2e8f0;
  --border-highlight: #cbd5e1;

